import { useState, type ChangeEvent, type FormEvent } from 'react';
import { Button, Input } from '@jinx-ui/react';

type RegistrationValues = {
  name: string;
  email: string;
  phone: string;
  country: string;
  city: string;
  street: string;
  zip: string;
};

type RegistrationWizardProps = {
  onSubmit: (values: RegistrationValues) => void;
};

const STEPS = ['Контакты', 'Адрес', 'Проверка'];

const EMPTY_VALUES: RegistrationValues = {
  name: '',
  email: '',
  phone: '',
  country: '',
  city: '',
  street: '',
  zip: '',
};

const SUMMARY: Array<[keyof RegistrationValues, string]> = [
  ['name', 'Имя'],
  ['email', 'Email'],
  ['phone', 'Телефон'],
  ['country', 'Страна'],
  ['city', 'Город'],
  ['street', 'Улица, дом'],
  ['zip', 'Индекс'],
];

export default function RegistrationWizard({ onSubmit }: RegistrationWizardProps) {
  const [step, setStep] = useState(0);
  const [values, setValues] = useState<RegistrationValues>(EMPTY_VALUES);

  const isLastStep = step === STEPS.length - 1;

  const handleChange =
    (field: keyof RegistrationValues) => (event: ChangeEvent<HTMLInputElement>) => {
      setValues((previous) => ({ ...previous, [field]: event.target.value }));
    };

  const handleSubmit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    if (!isLastStep) {
      setStep((previous) => previous + 1);
      return;
    }
    onSubmit(values);
  };

  const renderField = (
    field: keyof RegistrationValues,
    label: string,
    type: string = 'text',
    autoComplete?: string,
  ) => (
    <div
      className="jx-field"
      style={{ display: 'grid', gap: 'var(--jx-space-1)' }}
    >
      <label className="jx-label" htmlFor={`registration-${field}`}>
        {label}
      </label>
      <Input
        id={`registration-${field}`}
        name={field}
        type={type}
        autoComplete={autoComplete}
        value={values[field]}
        onChange={handleChange(field)}
      />
    </div>
  );

  return (
    <form
      className="jx-card jx-stack"
      onSubmit={handleSubmit}
      style={{ display: 'grid', gap: 'var(--jx-space-4)', padding: 'var(--jx-space-4)' }}
    >
      <nav aria-label="Шаги регистрации">
        <ol
          className="jx-steps"
          style={{
            display: 'flex',
            gap: 'var(--jx-space-2)',
            listStyle: 'none',
            margin: 0,
            padding: 0,
          }}
        >
          {STEPS.map((title, index) => (
            <li
              key={title}
              className="jx-step"
              data-state={index === step ? 'current' : index < step ? 'done' : 'upcoming'}
              aria-current={index === step ? 'step' : undefined}
              style={{
                flex: 1,
                display: 'flex',
                alignItems: 'center',
                gap: 'var(--jx-space-2)',
                padding: 'var(--jx-space-2)',
              }}
            >
              <span className="jx-step__index">{index + 1}</span>
              <span className="jx-step__title">{title}</span>
            </li>
          ))}
        </ol>
      </nav>

      {step === 0 && (
        <fieldset
          className="jx-fieldset"
          style={{ display: 'grid', gap: 'var(--jx-space-3)', border: 'none', margin: 0, padding: 0 }}
        >
          <legend className="jx-legend">Контакты</legend>
          {renderField('name', 'Имя', 'text', 'name')}
          {renderField('email', 'Email', 'email', 'email')}
          {renderField('phone', 'Телефон', 'tel', 'tel')}
        </fieldset>
      )}

      {step === 1 && (
        <fieldset
          className="jx-fieldset"
          style={{ display: 'grid', gap: 'var(--jx-space-3)', border: 'none', margin: 0, padding: 0 }}
        >
          <legend className="jx-legend">Адрес</legend>
          {renderField('country', 'Страна', 'text', 'country-name')}
          {renderField('city', 'Город', 'text', 'address-level2')}
          {renderField('street', 'Улица, дом', 'text', 'street-address')}
          {renderField('zip', 'Индекс', 'text', 'postal-code')}
        </fieldset>
      )}

      {step === 2 && (
        <section className="jx-stack" aria-label="Проверка данных">
          <h2 className="jx-heading">Проверка</h2>
          <dl
            className="jx-summary"
            style={{ display: 'grid', gap: 'var(--jx-space-2)', margin: 0 }}
          >
            {SUMMARY.map(([field, label]) => (
              <div
                key={field}
                style={{
                  display: 'flex',
                  justifyContent: 'space-between',
                  gap: 'var(--jx-space-3)',
                }}
              >
                <dt className="jx-summary__term">{label}</dt>
                <dd className="jx-summary__value" style={{ margin: 0 }}>
                  {values[field] || '—'}
                </dd>
              </div>
            ))}
          </dl>
        </section>
      )}

      <div
        className="jx-cluster"
        style={{
          display: 'flex',
          justifyContent: 'space-between',
          gap: 'var(--jx-space-2)',
        }}
      >
        <Button
          type="button"
          disabled={step === 0}
          onClick={() => setStep((previous) => previous - 1)}
        >
          Назад
        </Button>
        <Button type="submit">{isLastStep ? 'Отправить' : 'Дальше'}</Button>
      </div>
    </form>
  );
}

